import { DEVELOPER } from "./actionTypes";

export const initialState={
developers:[],
user:   {},
arr: []
}

function reducer(state, action) {
    switch (action.type) {
      case DEVELOPER:
        return (state += action.payload);
      default:
        return state;
    }
  }

  export default reducer
